// CSS Modules declarations
declare module '*.css' {
  const content: { [className: string]: string };
  export default content;
  export = content;
}

declare module '*.less' {
  const content: { [className: string]: string };
  export default content;
  export = content;
}

declare module '*.scss' {
  const content: { [className: string]: string };
  export default content;
  export = content;
}

declare module '*.sass' {
  const content: { [className: string]: string };
  export default content;
  export = content;
}
